d positions 1 to 8\n# energy_sorted[0] = 23630 (position 1)\n# energy_sorted[1] = 24677 (position 2)\n# energy_sorted[2] = 25425 (position 3)\n# energy_sorted[3] = 25852 (position 4)\n# energy_sorted[4] = 26479 (position 5)\n# energy_sorted[5] = 28936 (position 6)\n# energy_sorted[6] = 32485 (position 7)\n\n# Wait, I had 8 values, let me re-check\nprint(\"Number of energy values:\", len(energy_values))\nprint(\"Energy values:\", energy_values)\n\n# Actually, I think I miscounted. Let me list them again:\n# 2012: 32485\n# 2013: 24677  \n# 2014: 23630\n# 2015: 25425\n# 2016: 25852\n# 2017: 25794\n# 2018: 26479\n# 2019: 28936\n\n# That's 8 values. Sorted:\n# 23630, 24677, 25425, 25794, 25852, 26479, 28936, 32485\n\nenergy_sorted = [23630, 24677, 25425, 25794, 25852, 26479, 28936, 32485]\nprint(\"Energy sorted (corrected):\", energy_sorted)\n\n# With n=8 (even):\n# Median = average of 4th and 5th values (positions 4 and 5, 1-indexed)\n# = (25794 + 25852)/2 = 25623\n\n# For Tukey exclusive method (exclude median from halves):\n# Since median is average of positions 4 and 5, the lower half is positions 1-4 \n# and upper half is positions 5-8\n\n# Lower half: positions 1-4 = 23630, 24677, 25425, 25794\n# Upper half: positions 5-8 = 25852, 26479, 28936, 32485\n\n# Q1 = median of lower half (positions 1-4, even count = 4)\n# Q1 = average of positions 2 and 3 = (24677 + 25425)/2 = 25051\n\n# Q3 = median of upper half (positions 5-8, even count = 4)\n# Q3 = average of positions 6 and 7 = (26479 + 28936)/2 = 27707.5\n\nprint(\"\\nEnergy Q3 (Tukey exclusive method):\", (26479 + 28936) / 2)\n\n# Department of Agriculture data\nagri_values = [139712, 155897, 141806, 139112, 138161, 127563, 136713, 150120]\nagri_sorted = sorted(agri_values)\nprint(\"\\nAgriculture sorted:\", agri_sorted)\n\n# Sorted: 127563, 136713, 138161, 139112, 139712, 141806, 150120, 155897\nagri_sorted = [127563, 136713, 138161, 139112, 139712, 141806, 150120, 155897]\n\n# Median = average of positions 4 and 5 = (139112 + 139712)/2 = 139412\n# Upper half (positions 5-8): 139712, 141806, 150120, 155897\n# Q3 = average of positions 6 and 7 = (141806 + 150120)/2 = 145963\n\nprint(\"\\nAgriculture Q3 (Tukey exclusive method):\", (141806 + 150120) / 2)\n\n# Now calculate difference\nenergy_q3 = (26479 + 28936) / 2\nagri_q3 = (141806 + 150120) / 2\n\nprint(f\"\\nEnergy Q3: {energy_q3}\")\nprint(f\"Agriculture Q3: {agri_q3}\")\nprint(f\"Difference (Energy - Agriculture): {energy_q3 - agri_q3}\")\nprint(f\"Difference (Agriculture - Energy): {agri_q3 - energy_q3}\")\nEOF"}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
